out["swiss"]={"airline":"Swiss","power":{"checked":D,"answer":"SWISS allows up to two power banks per passenger in hand baggage only, each up to 100 Wh (2 g lithium). They may not be used or charged on board except for approved medical devices. A power bank of 100 to 160 Wh needs SWISS's approval, which you request through the contact form when you book.","sections":[{"h":"🔋 What SWISS says about power banks","p":"From the SWISS page \"Electronic devices and batteries\" (Switzerland, English), read on %s."%D,"table":{"head":["Question","SWISS rule"],"rows":[["Limit","2 power banks per passenger, each max. 100 Wh or 2 g lithium"],["100 to 160 Wh","Needs SWISS transport approval, registered via the contact form at booking"],["Checked baggage","Not permitted"],["Using or charging","Prohibited, except for approved medical devices"],["Banned model","Mobikins MK-PB-04, on all Lufthansa Group flights"]]},"list":["<strong>Same rule across the group:</strong> SWISS belongs to the Lufthansa Group, which applies these rules from 15 January 2026."]}],"faq":[["How do I get approval for a larger power bank on SWISS?","Use the contact form on the SWISS electronic devices page when you book, for power banks between 100 and 160 Wh."],["Can I charge my phone from a power bank on SWISS?","No. SWISS prohibits charging and using power banks on board, except for approved medical devices."]],"sources":[["https://www.swiss.com/ch/en/prepare/baggage/electronic-devices-and-batteries","SWISS &mdash; Electronic devices and batteries"]]}}
